  // Mock de get shoe design
  getShoeDesign(): Observable<ShoeDesign[]> {
    const shoeDesignMock: ShoeDesign[] = this.setMockShoeDesignsOptions();
    //const shoeDesignMock: Users[] = [];
    /*return throwError(() => ({
        description: 'No se ha encontrado data'
    }))*/
    return of(shoeDesignMock);
  }

  // Mock de get shoe design detail
  getShoeDesignDetail(reference: string): Observable<ShoeDesignDetail> {
    const shoeDesignDetailSelect = this.setMockShoeDesignsDetailOptions().find((i) => i.reference === reference);
    if (shoeDesignDetailSelect) {
        let shoeDesignDetailMock: ShoeDesignDetail = shoeDesignDetailSelect
        return of(shoeDesignDetailMock);
    } else {
        return throwError(() => ({
        description: 'No se ha encontrado data'
    }))
    }
  }

